function SaveButton() {
  const [saved, setSaved] = useState(false);

  function handleClick() {
    document.querySelector('#status').textContent = 'Saved';
    setSaved(true);
  }

  return (
    <>
      <p id="status">{saved ? 'Saved' : 'Not saved'}</p>
      <button onClick={handleClick}>Save</button>
    </>
  );
}
